import React, { useState, useEffect } from 'react';
import { Routes, Route, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

// Layout
import Sidebar from './Dashboard/Layout/Sidebar';
import TopBar from './Dashboard/Layout/TopBar';
import MobileMenu from './Dashboard/Layout/MobileMenu';

// Widgets
import DashboardHome from './Dashboard/Widgets/DashboardHome';
import UsersPage from './Dashboard/Widgets/UsersPage';
import ProductsPage from './Dashboard/Widgets/ProductsPage';
import OrdersPage from './Dashboard/Widgets/OrdersPage';
import AnalyticsPage from './Dashboard/Widgets/AnalyticsPage';
import MessagesPage from './Dashboard/Widgets/MessagesPage';
import SettingsPage from './Dashboard/Widgets/SettingsPage';

const Dashboard = ({ onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(() => window.innerWidth >= 1024);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [isLoading, setIsLoading] = useState(true);
  const [user, setUser] = useState(null);

  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      if (!mobile) setMobileMenuOpen(false);
    };

    window.addEventListener('resize', handleResize);
    handleResize();

    // Vérifier l'authentification
    checkAuth();

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const checkAuth = async () => {
    try {
      setIsLoading(true);

      // Vérifier le token dans localStorage
      const token = localStorage.getItem('authToken');
      const userDataStr = localStorage.getItem('userData');

      if (!token) {
        console.warn('Aucun token trouvé, redirection vers login');
        navigate('/login');
        return;
      }

      if (!userDataStr) {
        console.warn('Aucune donnée utilisateur trouvée');
        navigate('/login');
        return;
      }

      const userData = JSON.parse(userDataStr);

      // Vérifier si le token est expiré
      try {
        const payload = JSON.parse(atob(token.split('.')[1]));
        const isExpired = payload.exp * 1000 < Date.now();

        if (isExpired) {
          console.warn('Token expiré');
          localStorage.removeItem('authToken');
          localStorage.removeItem('userData');
          navigate('/login');
          return;
        }
      } catch (e) {
        console.warn('Erreur de décodage du token:', e);
      }

      setUser(userData);
      console.log('Utilisateur authentifié:', userData);

    } catch (error) {
      console.error('Erreur d\'authentification:', error);
      navigate('/login');
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userData');
    localStorage.removeItem('userRole');

    if (onLogout) onLogout();
    navigate('/login');
  };

  const toggleSidebar = () => {
    if (isMobile) {
      setMobileMenuOpen(!mobileMenuOpen);
    } else {
      setSidebarOpen(!sidebarOpen);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-neutral-50 to-primary-50 dark:from-neutral-950 dark:to-primary-950">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-500 mx-auto mb-4"></div>
          <p className="text-neutral-600 dark:text-neutral-400">Vérification de l'authentification...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return null; // La redirection est gérée dans checkAuth
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-neutral-50 to-primary-50 dark:from-neutral-950 dark:to-primary-950">
      <Sidebar 
        sidebarOpen={isMobile ? mobileMenuOpen : sidebarOpen}
        location={location}
        onLogout={handleLogout}
        isMobile={isMobile}
        userRole={user.role || 'user'}
        user={user}
      />

      <div className={`transition-all duration-300 ${isMobile ? '' : 'lg:pl-64'}`}>
        <TopBar 
          mobileMenuOpen={mobileMenuOpen}
          setMobileMenuOpen={setMobileMenuOpen}
          currentPath={location.pathname}
          toggleSidebar={toggleSidebar}
          isMobile={isMobile}
          user={user}
        />

        <main className="p-4 md:p-6">
          <Routes>
            <Route path="/" element={<DashboardHome user={user} />} />

            {/* Routes admin uniquement */}
            {user.role === 'admin' && (
              <>
                <Route path="users" element={<UsersPage user={user} />} />
                <Route path="products" element={<ProductsPage user={user} />} />
                <Route path="orders" element={<OrdersPage user={user} />} />
                <Route path="analytics" element={<AnalyticsPage user={user} />} />
              </>
            )}

            {/* Routes accessibles aux deux rôles */}
            <Route path="messages" element={<MessagesPage user={user} />} />
            <Route path="settings" element={<SettingsPage user={user} />} />
          </Routes>
        </main>
      </div>

      <MobileMenu 
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
        user={user}
        onLogout={handleLogout}
      />
    </div>
  );
};

export default Dashboard;
